// Settings come from the summers.datastore.config.keys data table: { CATEGORY: { key: value } }.
const parse = v => {
  if (v === null || v === undefined) return null;
  const s = String(v).trim();
  if (/^(true|false)$/i.test(s)) return s.toLowerCase() === 'true';
  if (/^-?\d+(\.\d+)?$/.test(s)) return Number(s);
  if (/^[\[{]/.test(s)) { try { return JSON.parse(s); } catch (e) { /* keep as text */ } }
  return s;
};
const cfg = {};
for (const { json: r } of $input.all()) {
  if (!r || !r.category || !r.key) continue;
  (cfg[r.category] ||= {})[r.key] = parse(r.value);
}
// Fail loudly if a required setting is missing, rather than running with a guess.
const REQUIRED = ["EMAIL_CONFIG.error_notify_to"];
const missing = REQUIRED.filter(p => { const [c, k] = p.split('.'); const v = cfg[c]?.[k]; return v === undefined || v === null || v === ''; });
if (missing.length) throw new Error('Missing settings in summers.datastore.config.keys: ' + missing.join(', '));
return [{ json: { cfg } }];

const CONFIG = { NOTIFY_TO: $('Build Config').first().json.cfg.EMAIL_CONFIG.error_notify_to };
const e = $('Error Trigger').first().json;
const esc = v => String(v ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const rows = [
  ['Workflow', e.workflow?.name], ['Failed node', e.execution?.lastNodeExecuted],
  ['Error', e.execution?.error?.message], ['Execution', e.execution?.url || e.execution?.id], ['Mode', e.execution?.mode],
].filter(([, v]) => v);
const html = `<div style="font-family:Lato,Arial,sans-serif;font-size:14px;color:#111827;max-width:640px">` +
  `<h3 style="color:#462CED;margin:0 0 8px">AP automation error</h3><table style="border-collapse:collapse;width:100%">` +
  rows.map(([k, v]) => `<tr><td style="padding:6px;font-weight:bold;width:30%;color:#374151">${esc(k)}</td><td style="padding:6px">${esc(v)}</td></tr>`).join('') +
  `</table></div>`;
return [{ json: { to: CONFIG.NOTIFY_TO, subject: `[AP workflow error] ${e.workflow?.name ?? 'unknown'}`, html } }];
